/**
 * @description Keeps secrets off the screens: in Preview payload and View request a header whose name looks like a
 * secret (authorization, token, secret, password, api-key, apikey, x-api-key, client_secret; any case) is shown masked,
 * e.g. "Bearer ••••".
 * @group Integration Hub
 */
public with sharing class IntegrationHubHeaderMask {

    /** @description Shown instead of a secret header value. */
    public static final String MASK = '••••';

    private static final List<String> SECRET_WORDS = new List<String>{
        'authorization', 'token', 'secret', 'password', 'api-key', 'apikey', 'x-api-key', 'client_secret'
    };
    private static final Set<String> SCHEMES = new Set<String>{
        'bearer', 'basic', 'token', 'digest', 'negotiate', 'apikey', 'sso-key', 'aws4-hmac-sha256'
    };

    /**
     * @description True for a header whose value is a secret: its name contains authorization, token, secret,
     * password, api-key, apikey, x-api-key or client_secret (any case).
     * @param headerName the header name
     * @return whether the value must be masked
     */
    public static Boolean isSecretHeader(String headerName) {
        String name = headerName == null ? '' : headerName.toLowerCase();
        for (String word : SECRET_WORDS) {
            if (name.contains(word)) {
                return true;
            }
        }
        return false;
    }

    /**
     * @description A header value as it may be shown: a secret is masked, keeping a scheme word, e.g. "Bearer ••••".
     * Salesforce merge fields such as {!$Credential.Partner.apiKey} are not secrets and stay as they are.
     * @param headerName the header name
     * @param value the value
     * @return the value to show
     */
    public static String maskValue(String headerName, String value) {
        if (!isSecretHeader(headerName) || String.isBlank(value) || value.trim().startsWith('{!')) {
            return value;
        }
        String first = value.trim().substringBefore(' ');
        return value.trim().contains(' ') && SCHEMES.contains(first.toLowerCase()) ? first + ' ' + MASK : MASK;
    }
}
